&lt;p&gt;&lt;strong&gt;The Basics:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW257934258 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;Advanced Consulting Engineers (ACEs) are&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;post-sale product experts that communicate technical nuances to &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;assist&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt; Tanium customers as they articulate their business &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;objectives&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;. A highly experienced technical resource, ACEs are engaged by Customer Success &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;to handle extraordinary customer engagement issues &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;(&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;e.g.&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;,&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt; stalled adoption) &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;at Enterprise and Major accounts and may be&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;l&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;everaged&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;by the broader account team &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;for short-term engagements &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;to &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;p&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;rovide&lt;/span&gt; &lt;span class=&quot;NormalTextRun SCXW257934258 BCX0&quot;&gt;product-specific guidance for advanced use cases.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW257934258 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You&#39;ll Do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:16711680,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:566,&amp;quot;335559991&amp;quot;:283,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Business Objective Realization:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Play a crucial role in the customer journey to operationalize business objectives and provide value realization in complex or stalled adoption.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:16711680,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:566,&amp;quot;335559991&amp;quot;:283,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;In-depth Knowledge Transfer:&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Involved in enabling end-users to effectively use Tanium products, to get past stalled adoption. &lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:16711680,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:566,&amp;quot;335559991&amp;quot;:283,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Post-sales Technical Advisory: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Support and document technical setup and configuration of complex products into runbooks, due to stalled adoption from the customer. Able to provide onsite technical assistance for support issues causing adoption and/or churn risk.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:16711680,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:566,&amp;quot;335559991&amp;quot;:283,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Post-engagement Feedback: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Following the engagement, provide documented feedback to Product, Engineering, Enablement, and Customer Service Operations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We&#39;re Looking For:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Education&lt;/span&gt;&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Associates degree or equivalent experience required&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bachelor degree in Computer Science, MIS, or similar experience a plus&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Must Have&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;8+ years in the industry with solid technical skills in multiple areas such as networking, security, operations, scripting, and/or programming.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Experience in one or more of the following technical domains: Endpoint Security, Endpoint Support/Troubleshooting, Incident Response, Systems Management, Utility Scripting (bash, PowerShell, VBScript, Python).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Extensive Hands-on Tanium experience&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Prior experience and breadth of knowledge needed to lead customers and internal teams.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Has mastered many new concepts and technologies; continually striving to master the Tanium platform and modules.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Critical thinking and problem solving; can break problems down into manageable, ordered piece parts and masterfully convey the problem statement and plan to others. Thinks critically, spanning the customer lifecycle, and develops new capabilities on the Tanium platform with a high level of autonomy.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Good Judgement; takes self-governed, consistent, action to prioritize and weigh cost and value in order to determine the action most appropriately aligned with the Tanium and our mission.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Independent; can work on the most complex problems; should be able to complete tasks that are not well documented; participate in projects specific to their current skills and follow established technical support procedures only requiring help on more complex initiatives or issues.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Communication; have mastered executive communication and demonstrate emotional intelligence, and patience, in all forms of communication. Anticipate blockers and delays for their work and the work of others, and communicate appropriately before requiring escalation.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Influencing; demonstrate strong and consistent influence skills, working effectively with their team and strategic customers, to present logical and compelling arguments to enhance innovation and efficiencies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Informal Leadership; constructively lead in recognizing when conditions have changed and the team needs to adapt. This requires an attitude and drive that also leads the team in spotting emerging trends and patterns quickly, solving hard problems, and generating creative solutions.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;A deep sense of ownership in the work, no matter how small the task. Willing to jump into any effort to help the team succeed.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;A reputation within, and outside of, their team for being highly collaborative. They use this thinking to actively mentor and coach others to aid in their professional achievement and help avoid problems/high-risk behavior.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:4}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About Tanium&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;Tanium is the Autonomous IT company. Driven by AI and real-time endpoint intelligence, Tanium Autonomous IT empowers IT and security teams to make their organizations unstoppable.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Many of the world’s leading organizations trust Tanium’s single, unified platform for endpoint management and security to innovate faster, stay resilient and move business forward with confidence, at scale. To learn how Tanium delivers Autonomous IT for unstoppable business – visit &lt;u&gt;&lt;a id=&quot;OWA8cd82040-d6a4-2e07-8c22-f773746075e4&quot; href=&quot;http://www.tanium.com/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;0&quot;&gt;www.tanium.com&lt;/a&gt;&lt;/u&gt; and&amp;nbsp;follow us on &lt;u&gt;&lt;a id=&quot;OWA51246dd5-7f28-280e-6637-139dda4774bb&quot; href=&quot;https://www.linkedin.com/company/tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt; and &lt;u&gt;&lt;a id=&quot;OWAd79eefc3-ede9-5e26-14d4-517b82af2392&quot; href=&quot;https://twitter.com/Tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;2&quot;&gt;X&lt;/a&gt;&lt;/u&gt;.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;On a mission. Together.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Tanium, we are stewards of a culture that emphasizes the importance of collaboration, respect, and diversity. In our pursuit of revolutionizing the way some of the largest enterprises and governments in the world solve their most difficult IT challenges, we are strengthened by our unique perspectives and by our collective actions.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;As a global organization with stakeholders around the world, it’s imperative that the diversity of our customers and communities is reflected internally in our team members. We strive to create a diverse and inclusive environment where everyone feels they have opportunities to succeed and grow because we know that only together can we do great things. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our commitment to excellence and innovation has earned us a place on the Forbes Cloud 100 list for ten consecutive years, and we continue to be recognized worldwide as a great place to work.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Each of our team members has 5 days set aside as volunteer time off (VTO) to contribute to the communities they live in and give back to the causes they care about most.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll get&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The annual base salary range for this full-time position is $150,000 to $230,000. This range is an estimate for what Tanium will pay a new hire. The actual annual base salary offered may be adjusted based on a variety of factors, including but not limited to, location, education, skills, training, and experience.&lt;/p&gt;
&lt;p&gt;In addition to an annual base salary, team members will receive equity awards and a generous benefits package consisting of medical, dental and vision plan, family planning benefits, health savings account, flexible spending account, transportation savings account, 401(k) retirement savings plan with company match, life, accident and disability coverage, business travel accident insurance, employee assistance programs, disability insurance, and other well-being benefits.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Tanium is an Equal Opportunity and Affirmative Action employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, age, gender identity, sexual orientation, disability, protected Veteran status, or other legally protected categories. If you require a reasonable accommodation in searching for a job opening, completing an application, interviewing, or completing any pre-employment testing or requirements, please contact&amp;nbsp;&lt;a href=&quot;mailto:accommodations@tanium.com&quot;&gt;accommodations@tanium.com&lt;/a&gt;. For more information refer to the “Know Your Rights” poster which is available here -&amp;nbsp;&lt;a href=&quot;https://www.eeoc.gov/poster&quot; target=&quot;_blank&quot;&gt;https://www.eeoc.gov/poster&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;Please be aware of job offers coming from people claiming to be Tanium employees. Tanium employees will only use @tanium.com email addresses to communicate with you, will have video interviews with you, and will never ask you for money.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.cigna.com/legal/compliance/machine-readable-files&quot; target=&quot;_blank&quot;&gt;This link&lt;/a&gt; leads to the machine readable files that are made available in response to the federal Transparency in Coverage Rule and includes negotiated service rates and out-of-network allowed amounts between health plans and healthcare providers. The machine-readable files are formatted to allow researchers, regulators, and application developers to more easily access and analyze data.&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;For more information on how Tanium processes your personal data, please see our&amp;nbsp;&lt;a href=&quot;https://www.tanium.com/privacy-policy/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-safelink=&quot;true&quot; data-linkindex=&quot;0&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW233539685 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW233539685 BCX0&quot;&gt;The Basics&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW233539685 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:100,&amp;quot;335572079&amp;quot;:12,&amp;quot;335572080&amp;quot;:4,&amp;quot;335572081&amp;quot;:3349216,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We are looking for an AI Business Analyst to help the Corporate AI team turn ideas into working, measurable AI solutions. This is a hands-on role: you will gather requirements, evaluate tools, analyze processes and data, and support the team as it builds and rolls out AI capabilities across the enterprise. You will also own several of the operational pillars the program runs on, including intake management and outcome metrics, giving the Director and the team a clear, evidence-based view of what is working.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;The Director of the Corporate AI Program owns program strategy, priorities, and overall orchestration. The AI Business Analyst supports that strategy with analysis and carries a defined set of operational responsibilities, working as a producer alongside the AI engineers, the enablement lead, and stakeholders across the business rather than managing the program itself.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Join us if you like doing the analysis that turns ambiguity into clear, actionable work, if you take pride in measurement and follow-through, and if you thrive in a growing, collaborative, and innovative environment.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;This position follows the Company&#39;s hybrid schedule which currently requires employees to work in the office at one of the following locations a minimum of three days per week: Addison, TX; Bellevue, WA; Durham, NC; Emeryville, CA; or Reston, VA.&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span class=&quot;TextRun MacChromeBold SCXW24659873 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW24659873 BCX0&quot;&gt;We&#39;re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW24659873 BCX0&quot;&gt;&amp;nbsp;looking for someone with&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW24659873 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:100,&amp;quot;335572079&amp;quot;:12,&amp;quot;335572080&amp;quot;:4,&amp;quot;335572081&amp;quot;:3349216,&amp;quot;469789806&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Education&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet 2&quot;&gt;Bachelor&#39;s degree&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet 2&quot;&gt;required&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet 2&quot;&gt;; advanced degree or relevant certification (e.g., CBAP/CCBA, PMP) a plus&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Experience&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet 2&quot;&gt;4+ years in business analysis, technical or product analysis, or a similar role translating business needs into defined, actionable work&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
